"use client";
import { Popover } from "radix-ui";
import { Check,ChevronsUpDown,Search } from "lucide-react";
import { AnimatePresence,motion } from "motion/react";
import { useId,useState,type ComponentProps } from "react";
import { useAingMotion } from "@/registry/aing/lib/motion";
import { result,toolName,useWebMCPTool,type WebMCPProps } from "@/registry/aing/lib/webmcp";
export type ComboboxOption={value:string;label:string;disabled?:boolean};
export type ComboboxProps=Omit<ComponentProps<"button">,"value"|"defaultValue"|"onChange">&WebMCPProps&{options:ComboboxOption[];value?:string;defaultValue?:string;onValueChange?:(value:string)=>void;placeholder?:string;emptyText?:string};
export function Combobox({options,value,defaultValue="",onValueChange,placeholder="선택하세요",emptyText="검색 결과가 없습니다.",webmcp,toolName:name,className="",...props}:ComboboxProps){
 const id=useId(),[internal,setInternal]=useState(defaultValue),[open,setOpen]=useState(false),[query,setQuery]=useState(""),[active,setActive]=useState(0);const selected=value??internal,{reduced,transition}=useAingMotion(),label=props["aria-label"]??props.name??"Combobox";
 const filtered=options.filter(option=>option.label.toLocaleLowerCase().includes(query.toLocaleLowerCase())),enabled=filtered.filter(option=>!option.disabled),current=enabled[Math.min(active,Math.max(0,enabled.length-1))];
 const choose=(next:string)=>{setInternal(next);onValueChange?.(next);setOpen(false);};
 useWebMCPTool(webmcp===false?null:{name:toolName("choose",id,{webmcp,toolName:name},"",label),description:webmcp?.description??`${label} 옵션을 검색하고 선택합니다.`,inputSchema:{type:"object",properties:{value:{type:"string",enum:options.filter(o=>!o.disabled).map(o=>o.value)}},required:["value"],additionalProperties:false},execute:({value:next})=>{if(props.disabled||typeof next!=="string"||!options.some(o=>o.value===next&&!o.disabled))throw new Error("사용 가능한 옵션을 선택하세요.");choose(next);return result({value:next});}});
 return <Popover.Root open={open} onOpenChange={next=>{setOpen(next);setQuery("");setActive(0);}}><Popover.Trigger asChild><button {...props} type="button" role="combobox" aria-expanded={open} aria-controls={`${id}-list`} aria-label={label} className={`flex h-9 w-full min-w-0 items-center justify-between gap-3 rounded-md border border-input bg-background px-3 text-[13px] shadow-xs outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:opacity-45 ${className}`}><span className={`truncate ${selected?"":"text-muted-foreground"}`}>{options.find(o=>o.value===selected)?.label??placeholder}</span><ChevronsUpDown aria-hidden size={14} className="shrink-0 text-muted-foreground"/></button></Popover.Trigger><Popover.Portal forceMount><AnimatePresence>{open&&<Popover.Content forceMount asChild sideOffset={6} align="start"><motion.div initial={{opacity:0,scale:0.96,y:-4}} animate={{opacity:1,scale:1,y:0}} exit={{opacity:0,scale:0.98,y:-2,transition:reduced?{duration:0}:{duration:0.12}}} transition={reduced?{duration:0}:{...transition,opacity:{duration:0.12}}} style={{transformOrigin:"var(--radix-popover-content-transform-origin)"}} className="z-50 w-[var(--radix-popover-trigger-width)] overflow-hidden rounded-md border bg-popover text-popover-foreground shadow-md"><div className="flex items-center gap-2 border-b px-3"><Search aria-hidden size={14} className="text-muted-foreground"/><input role="combobox" aria-label={`${label} 검색`} aria-expanded={open} aria-controls={`${id}-list`} aria-autocomplete="list" aria-activedescendant={current?`${id}-${options.indexOf(current)}`:undefined} value={query} onChange={e=>{setQuery(e.target.value);setActive(0);}} onKeyDown={e=>{if(["ArrowDown","ArrowUp","Home","End"].includes(e.key)){e.preventDefault();setActive(n=>e.key==="Home"?0:e.key==="End"?enabled.length-1:(n+(e.key==="ArrowDown"?1:-1)+enabled.length)%Math.max(1,enabled.length));}if(e.key==="Enter"&&current){e.preventDefault();choose(current.value);}}} placeholder="검색…" className="h-10 w-full min-w-0 bg-transparent text-[13px] outline-none focus-visible:shadow-none"/></div><div id={`${id}-list`} role="listbox" aria-label={label} className="max-h-60 overflow-y-auto p-1">{filtered.length===0&&<p role="status" className="py-6 text-center text-xs text-muted-foreground">{emptyText}</p>}{filtered.map(option=><div key={option.value} id={`${id}-${options.indexOf(option)}`} role="option" aria-selected={selected===option.value} aria-disabled={option.disabled} onPointerMove={()=>{if(!option.disabled)setActive(enabled.indexOf(option));}} onMouseDown={e=>e.preventDefault()} onClick={()=>{if(!option.disabled)choose(option.value);}} className={`relative isolate flex cursor-default items-center justify-between rounded-sm px-2 py-2 text-[13px] ${option.disabled?"opacity-45":""}`}>{current===option&&!option.disabled&&<motion.span layoutId={`combobox-highlight-${id}`} transition={transition} className="absolute inset-0 -z-10 rounded-sm bg-accent"/>}{option.label}{selected===option.value&&<Check aria-hidden size={13}/>}</div>)}</div></motion.div></Popover.Content>}</AnimatePresence></Popover.Portal></Popover.Root>;
}
